/// Video frame streaming service
///
/// To build a server, implement a class that conforms to this protocol.
internal protocol Beebium_VideoServiceProvider: CallHandlerProvider {
  var interceptors: Beebium_VideoServiceServerInterceptorFactoryProtocol? { get }

  /// Stream frames as they complete (at VSYNC)
  func subscribeFrames(request: Beebium_SubscribeFramesRequest, context: StreamingResponseCallContext<Beebium_Frame>) -> EventLoopFuture<GRPCStatus>

  /// The frame the machine completed at or after an emulated cycle: for a
  /// client that has run to a known cycle and wants the field the guest was
  /// drawing into then, not whichever frame happens to be current.
  ///
  /// Returns the earliest frame the server sees whose cycle_count is at least
  /// after_cycle: the current frame if it already qualifies (only the latest
  /// frame is held, so one that qualified before it cannot be returned),
  /// otherwise the next to complete; never one stamped before after_cycle.
  /// The machine must run for a later frame to complete. Fails with
  /// DEADLINE_EXCEEDED if none arrives within timeout_ms.
  func captureFrame(request: Beebium_CaptureFrameRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_Frame>

  /// Get current video configuration
  func getConfig(request: Beebium_GetConfigRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_VideoConfig>

  /// Read the MODE 7 screen as characters rather than pixels.
  ///
  /// A snapshot rather than a stream: a caller wants one screen when it asks
  /// -- a copy command, or a script reading the display -- and pushing 8 KB
  /// of cell data per frame to every client on the chance that someone might
  /// copy would be absurd. A future vector renderer needs every frame aligned
  /// with the pixels it replaces, and that is a separate transport from the
  /// same capture; see docs/discussion/teletext-cell-capture.md.
  func getTeletextScreen(request: Beebium_GetTeletextScreenRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_TeletextScreen>

  /// Where the screen the video shows lies in memory, from how the 6845, the
  /// System VIA latch and the machine's paging are programmed now -- not from
  /// a screen mode -- so a client can read the screen's bytes from the named
  /// region: GetMemoryRegions lists it, and its addresses are CPU addresses.
  func getScreenSource(request: Beebium_GetScreenSourceRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_ScreenSource>

  /// Read text from the display, whatever mode is producing it.
  ///
  /// The caller selects in pixels and gets back text plus where it was found.
  /// A pixel rectangle is something a client can produce from a drag without
  /// knowing anything about modes, grids or cell sizes, and the strategy that
  /// reads a given band of scanlines is the server's business.
  func getScreenText(request: Beebium_GetScreenTextRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_ScreenText>

  /// Report the character grid the display currently implies, per band.
  ///
  /// Separate from GetScreenText because snapping a drag has to happen while
  /// the drag is in progress, when the client has nothing to send yet.
  func getScreenGeometry(request: Beebium_GetScreenGeometryRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_ScreenGeometry>

  /// Hold the screen as it is now, so a selection reads the still it was drawn
  /// on rather than whatever the machine has drawn since.
  ///
  /// A read depends on four things that move independently -- the pixels, the
  /// band geometry, the teletext grid, and the font in RAM, which VDU 23 can
  /// redefine at any moment. Reading them at four different instants describes
  /// a screen that never existed, and on a moving display the text a user
  /// copies is not the text they selected. So they are captured together, and
  /// later reads name the capture.
  ///
  /// The emulator keeps running: a hold is a copy, not a pause. Nothing about
  /// holding a screen reaches the machine or any other client.
  func holdScreen(request: Beebium_HoldScreenRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_ScreenHold>

  /// Release a held screen. Holds expire on their own so a client that dies
  /// does not leak one, but a client that has finished should say so.
  func releaseScreen(request: Beebium_ReleaseScreenRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_ReleaseScreenResponse>
}

